!function(){"use strict";document.addEventListener("DOMContentLoaded",function(){!function(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",function(){document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");try{const t=JSON.parse(localStorage.getItem("iie_storage")||"{}");t.theme=e?"light":"dark",localStorage.setItem("iie_storage",JSON.stringify(t))}catch(t){localStorage.setItem("theme",e?"light":"dark")}});const t=document.getElementById("menu-toggle"),a=document.getElementById("nav-menu");t&&a&&t.addEventListener("click",function(){const e="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",!e),a.classList.toggle("active")})}(),function(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".itd-section");e.forEach(a=>{a.addEventListener("click",function(){const a=this.getAttribute("data-tab");e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),this.classList.add("active"),this.setAttribute("aria-selected","true"),t.forEach(e=>{e.getAttribute("data-tab")===a?e.classList.add("active"):e.classList.remove("active")}),window.scrollTo({top:0,behavior:"smooth"})})})}(),function(){const e=document.getElementById("btn-scroll-top");if(!e)return;e.addEventListener("click",function(){window.scrollTo({top:0,behavior:"smooth"})}),window.addEventListener("scroll",function(){window.scrollY>400?e.classList.add("show"):e.classList.remove("show")})}(),function(){const t=document.querySelectorAll(".itd-marker"),a=document.querySelectorAll(".itd-legend-btn"),o=document.getElementById("itd-part-title"),r=document.getElementById("itd-part-example"),n=document.getElementById("itd-part-body");function i(i){const s=e[i];s&&(o&&(o.textContent=s.title),r&&(r.textContent=s.example),n&&(n.textContent=s.body),t.forEach(e=>{e.classList.toggle("active",e.getAttribute("data-part")===i)}),a.forEach(e=>{e.classList.toggle("active",e.getAttribute("data-part")===i)}))}t.forEach(e=>{e.addEventListener("click",function(){i(this.getAttribute("data-part"))})}),a.forEach(e=>{e.addEventListener("click",function(){i(this.getAttribute("data-part"))})})}()});const e={crown:{title:"The Crown Finial",example:"Ashoka Chakra disc • Durand President’s Cup",body:"The crown, or finial, is the trophy’s signature. On Indian trophies it frequently carries a national symbol — the Durand President’s Cup features a circular disc atop the Ashoka Lion Capital — or a figure of the sportsperson the award honours, as with the statuettes of Arjuna and Dhyan Chand. The finial says: the nation, or the hero, watches over this prize."},bowl:{title:"The Bowl",example:"Grecian urn • Ranji Trophy",body:"The bowl is the vessel of victory — the part a winner lifts and shows to the crowd. Anthony de Mello’s 1934 sketch for the Ranji Trophy was a Grecian urn two feet high with a lid, the handle of which represented Father Time. An open bowl, as in the Durand Cup, invites the ritual lift; a lidded urn carries remembrance."},emblem:{title:"The Sport Emblem",example:"Snake boat • Nehru Trophy",body:"The emblem on the trophy’s face mirrors the sport. The Nehru Trophy is itself a silver replica of a chundan vallam (snake boat); cricket trophies carry bat-and-ball motifs; football honours are silver bowls. When the emblem becomes the trophy’s own form, the trophy becomes a miniature of the game."},handle:{title:"The Handle",example:"Father Time • Ranji design",body:"Handles are sculptural and symbolic. The Ranji Trophy’s original design set Father Time as the handle of the urn — the god of cricket’s passage of time, borrowed from the Lord’s weathervane. Handles are also functional: they are made to be gripped for the victory lift."},band:{title:"The Inscription Band",example:"Engraved winners & donors",body:"The inscription band is the trophy’s memory. Champion names are engraved year after year, turning the trophy into a roll of honour; donors and dedications are recorded too. The Nehru Trophy bears its famous engraved words — “To the winners of the boat race which is a unique feature of community life in Travancore Cochin” — above Nehru’s signature."},stem:{title:"The Stem & Collar",example:"Knop & collar • silver work",body:"The stem, or waist, connects bowl and base with a collar and knop — flourishes inherited from Victorian silver craft. It gives the trophy height and presence, drawing the eye upward from the base to the bowl: from the ground of the game to the crown of victory."},base:{title:"The Base Plinth",example:"Wooden abacus • Nehru Trophy",body:"The plinth grounds the prize. Indian trophies pair precious metal with craft materials: the Nehru Trophy’s silver snake boat rests on a wooden abacus, the boat-builder’s measuring platform. Tiered silver plinths add height and ceremonial weight; each material roots the trophy in a place and a craft."},motto:{title:"The Motto Ribbon",example:"“Satyameva Jayate” • donor dedications",body:"The lowest inscription is often the motto. Beneath the State Emblem stands “Satyameva Jayate” — Truth alone triumphs — the pattern set by the Bharat Ratna medal. Donor dedications fill the same space on older trophies, so the base of a trophy always carries the reason it exists."}}}();